/**
 * No existe o el usuario no tiene acceso: un cuidador que pide un paciente sin vínculo
 * activo (o sus recursos) recibe 404, igual que si no existiera, para no revelar datos
 * ajenos.
 */
export type NotFoundResponse = Problem;

/**
 * Conflicto con el estado actual (por ejemplo, correo ya registrado).
 */
export type ConflictResponse = Problem;

/**
 * La petición no cumple el esquema.
 */
export type ValidationErrorResponse = ValidationProblem;

/**
 * Límite de peticiones superado.
 */
export type TooManyRequestsResponse = Problem;

/**
 * Token de un solo uso inválido, caducado o ya usado (`code: invalid_token`).
 */
export type InvalidTokenResponse = Problem;

/**
 * El proveedor externo (modelo de IA) no responde (`code: chat_unavailable`). Se puede
 * reintentar; no consume el límite diario.
 */
export type ServiceUnavailableResponse = Problem;

